// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address caller, uint256 amount, address other) public {
        vm.assume(caller != address(0));
        vm.assume(other != address(0));
        vm.assume(caller != other);
        vm.assume(amount > 0);
        vm.assume(amount <= type(uint256).max / 2);

        uint256 callerBefore = c.getBalance(caller);
        uint256 otherBefore = c.getBalance(other);

        vm.deal(caller, amount);
        vm.prank(caller);
        c.addToBalance{value: amount}();

        uint256 callerAfter = c.getBalance(caller);
        uint256 otherAfter = c.getBalance(other);

        assertTrue(callerAfter >= callerBefore + amount && otherAfter >= otherBefore);
    }
}
